using System.Net;
using System.Net.Http.Json;
using BuildingFlow.Application;
using BuildingFlow.Domain;
using Xunit;
namespace BuildingFlow.IntegrationTests;
public sealed class MobileManagerTests(SiteApiTests.SiteApiFactory factory):IClassFixture<SiteApiTests.SiteApiFactory>{
 private async Task<(string User,Guid Property,Guid Membership)> Setup(){
  var user=Guid.NewGuid().ToString();var p=new Property("Manager fixture","City","District","Address");var b=p.AddBuilding("A");var u=b.AddUnit("1",1,90m);for(var i=2;i<=51;i++)b.AddUnit(i.ToString(),1,90m);
  var person=new Person(p.Id,"Resident","Fixture","5550000000","private@example.test");person.SetProfile("NATURAL","FOREIGN","US","SECRET123",null,null,null,null);
  var today=DateOnly.FromDateTime(TimeZoneInfo.ConvertTime(DateTimeOffset.UtcNow,TimeZoneInfo.FindSystemTimeZoneById("Europe/Istanbul")).DateTime);
  var occupancy=new UnitOccupancy(p.Id,u.Id,person.Id,OccupancyType.TENANT,today.AddYears(-1));var owner=new UnitOccupancy(p.Id,u.Id,person.Id,OccupancyType.OWNER,today.AddYears(-1));
  var future=new Person(p.Id,"Future","Hidden");var futureLink=new UnitOccupancy(p.Id,u.Id,future.Id,OccupancyType.RESIDENT,today.AddDays(1));
  var member=new PropertyMembership(p.Id,user);var a=new DuesAssessment(p.Id,Guid.NewGuid(),new string('a',64),new DateOnly(today.Year,today.Month,1),100m,"TRY",today.AddDays(-1),"fixture");a.AddCharge(u.Id);
  var draft=new Announcement(p.Id,"Management draft","Fixture only",ContentAudience.MANAGEMENT);
  await factory.WithDb(async db=>{db.AddRange(p,member,person,occupancy,owner,future,futureLink,a,draft,new MobileRequest(Guid.NewGuid(),p.Id,u.Id,"TENANT","another-user","Fixture request"));await db.SaveChangesAsync();});return(user,p.Id,member.Id);
 }
 private static string Path(Guid p,string role="MANAGER",string section="overview",int page=1)=>$"/api/v1/mobile/manager?propertyId={p}&role={role}&section={section}&page={page}";
 [PostgresFact]public async Task ManagerSummaryAndResidentsAreMinimalCurrentAndScoped(){var s=await Setup();using var c=TestToken.Client(factory,s.User,"MANAGER");var d=(await c.GetFromJsonAsync<ManagerSnapshot>(Path(s.Property)))!;Assert.Equal(51,d.Summary.Units);Assert.Equal(1,d.Summary.Residents);Assert.Equal("100.00",d.Summary.Balance);Assert.Equal("100.00",d.Summary.Overdue);Assert.Equal(1,d.Summary.Requests);var response=await c.GetAsync(Path(s.Property,section:"residents"));var json=await response.Content.ReadAsStringAsync();Assert.DoesNotContain("private@example.test",json);Assert.DoesNotContain("SECRET123",json);Assert.DoesNotContain("5550000000",json);Assert.DoesNotContain("Future",json);var residents=(await response.Content.ReadFromJsonAsync<ManagerSnapshot>())!;Assert.Equal(2,residents.Total);Assert.All(residents.Rows,r=>Assert.Equal("Resident Fixture",r.Title));Assert.Equal("Fixture request",Assert.Single((await c.GetFromJsonAsync<ManagerSnapshot>(Path(s.Property,section:"requests")))!.Rows).Detail);Assert.Equal("DRAFT",Assert.Single((await c.GetFromJsonAsync<ManagerSnapshot>(Path(s.Property,section:"announcements")))!.Rows).State);}
 [PostgresFact]public async Task UnitsAreBoundedStableAndTotalsSpanPages(){var s=await Setup();using var c=TestToken.Client(factory,s.User,"MANAGER");var first=(await c.GetFromJsonAsync<ManagerSnapshot>(Path(s.Property,section:"units")))!;var second=(await c.GetFromJsonAsync<ManagerSnapshot>(Path(s.Property,section:"units",page:2)))!;Assert.Equal(50,first.Rows.Length);Assert.Single(second.Rows);Assert.Equal(51,second.Total);Assert.Empty(first.Rows.Select(x=>x.Id).Intersect(second.Rows.Select(x=>x.Id)));Assert.Equal("100.00",second.Summary.Balance);Assert.Single((await c.GetFromJsonAsync<ManagerSnapshot>(Path(s.Property,section:"finance")))!.Rows);Assert.Single((await c.GetFromJsonAsync<ManagerSnapshot>(Path(s.Property,section:"buildings")))!.Rows);}
 [PostgresFact]public async Task RolesMembershipRevocationAndForeignPropertiesFailClosed(){var s=await Setup();using var manager=TestToken.Client(factory,s.User,"MANAGER");using var owner=TestToken.Client(factory,s.User,"OWNER");using var accountant=TestToken.Client(factory,s.User,"ACCOUNTANT");using var stranger=TestToken.Client(factory,Guid.NewGuid().ToString(),"MANAGER");using var anon=TestToken.Client(factory,null,"");Assert.Equal(HttpStatusCode.Unauthorized,(await anon.GetAsync(Path(s.Property))).StatusCode);foreach(var c in new[]{owner,accountant,stranger})Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(s.Property))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await accountant.GetAsync(Path(s.Property,"ACCOUNTANT","residents"))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await manager.GetAsync(Path(s.Property,"SUPER_ADMIN"))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await manager.GetAsync(Path(Guid.NewGuid()))).StatusCode);await factory.WithDb(async db=>{var m=await db.PropertyMemberships.FindAsync(s.Membership);m!.SetEnabled(false);await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.Forbidden,(await manager.GetAsync(Path(s.Property))).StatusCode);}
 [PostgresFact]public async Task SuperAdminScopeAndInvalidPaging(){var s=await Setup();using var c=TestToken.Client(factory,Guid.NewGuid().ToString(),"SUPER_ADMIN");Assert.Equal(HttpStatusCode.OK,(await c.GetAsync(Path(s.Property,"SUPER_ADMIN"))).StatusCode);foreach(var page in new[]{0,-1,10001})Assert.Equal(HttpStatusCode.BadRequest,(await c.GetAsync(Path(s.Property,"SUPER_ADMIN",page:page))).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await c.GetAsync(Path(s.Property,"SUPER_ADMIN","unknown"))).StatusCode);await factory.WithDb(async db=>{var p=await db.Properties.FindAsync(s.Property);p!.SetEnabled(false);await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(s.Property,"SUPER_ADMIN"))).StatusCode);}
}
